-- Grace Bells, Primary 5 English, Comprehension and Vocabulary.
--
-- The original questions for this topic were written around one reading passage
-- that only the first question carried, so the game could not ask the rest.
-- Run 20261106_question_quality.sql first: it sets those aside. This adds 30
-- replacement questions (6 for each of the 5 levels), each carrying its own short
-- text, so every one can be answered on its own, in any order.
--
-- Safe to run more than once.

update public.institution_curricula c
   set generated_questions = c.generated_questions || $j$[{"type": "multiple_choice", "question": "Read: “Tobi sells oranges at the market every Saturday. He wakes up at five o’clock to carry the baskets.” What does Tobi sell?", "options": ["A. Mangoes", "B. Oranges", "C. Bread", "D. Fish"], "answer": "B. Oranges", "narrative_success": "You read the order exactly right. Table served!", "narrative_failure": "Not quite. Read the order again, slowly.", "concept": "Finding a stated detail.", "level": "foundation", "level_label": "Foundation", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “The library opens at eight in the morning and closes at four in the afternoon. It is closed on Sundays.” When does the library close?", "options": ["A. At eight in the morning", "B. At four in the afternoon", "C. At twelve noon", "D. On Sunday morning"], "answer": "B. At four in the afternoon", "narrative_success": "You read the order exactly right. Table served!", "narrative_failure": "Not quite. Read the order again, slowly.", "concept": "Finding a stated time.", "level": "foundation", "level_label": "Foundation", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Amina has two brothers and one sister. Her youngest brother is called Sola.” How many brothers does Amina have?", "options": ["A. One", "B. Two", "C. Three", "D. Four"], "answer": "B. Two", "narrative_success": "You read the order exactly right. Table served!", "narrative_failure": "Not quite. Read the order again, slowly.", "concept": "Finding a stated number.", "level": "foundation", "level_label": "Foundation", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “A heavy rain fell all night. In the morning, the road to the village was covered with water.” What covered the road in the morning?", "options": ["A. Sand", "B. Leaves", "C. Water", "D. Snow"], "answer": "C. Water", "narrative_success": "You read the order exactly right. Table served!", "narrative_failure": "Not quite. Read the order again, slowly.", "concept": "Finding a stated detail.", "level": "foundation", "level_label": "Foundation", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Chidi planted a mango seed behind his house. After five years, it grew into a tall tree with sweet fruit.” How long did the mango seed take to grow into a tall tree?", "options": ["A. One year", "B. Two years", "C. Five years", "D. Ten years"], "answer": "C. Five years", "narrative_success": "You read the order exactly right. Table served!", "narrative_failure": "Not quite. Read the order again, slowly.", "concept": "Finding a stated time.", "level": "foundation", "level_label": "Foundation", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “The school bell rings at ten o’clock for break. Pupils then play in the field or eat in the hall.” What happens when the bell rings at ten o’clock?", "options": ["A. School closes for the day", "B. Pupils go on break", "C. Exams begin", "D. Pupils go home"], "answer": "B. Pupils go on break", "narrative_success": "You read the order exactly right. Table served!", "narrative_failure": "Not quite. Read the order again, slowly.", "concept": "Understanding what happens in a sequence.", "level": "foundation", "level_label": "Foundation", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Bees visit flowers to drink nectar. While they drink, pollen sticks to their legs and falls on the next flower. This helps plants make seeds.” Which sentence gives the main idea?", "options": ["A. Bees help plants make seeds by carrying pollen.", "B. Bees live in hives.", "C. Flowers are always yellow.", "D. Pollen is sweet to eat."], "answer": "A. Bees help plants make seeds by carrying pollen.", "narrative_success": "Spot on. The customer is happy with your reading.", "narrative_failure": "Look again at the words the customer used.", "concept": "Finding the main idea.", "level": "beginner", "level_label": "Beginner", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “The lion is called the king of the jungle, yet it spends most of the day sleeping to save its energy for hunting.” What does ‘save’ mean here?", "options": ["A. Keep for later", "B. Throw away", "C. Break", "D. Sell"], "answer": "A. Keep for later", "narrative_success": "Spot on. The customer is happy with your reading.", "narrative_failure": "Look again at the words the customer used.", "concept": "Working out a word from its sentence.", "level": "beginner", "level_label": "Beginner", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “The tired traveller sat under a tree to rest because the afternoon sun was scorching.” Which word means ‘extremely hot’?", "options": ["A. Tired", "B. Rest", "C. Scorching", "D. Afternoon"], "answer": "C. Scorching", "narrative_success": "Spot on. The customer is happy with your reading.", "narrative_failure": "Look again at the words the customer used.", "concept": "Finding a word from its meaning.", "level": "beginner", "level_label": "Beginner", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Mum asked Bola to tidy her room. Bola picked up her clothes, arranged her books and swept the floor.” What does ‘tidy’ mean here?", "options": ["A. Make neat", "B. Paint", "C. Break", "D. Hide"], "answer": "A. Make neat", "narrative_success": "Spot on. The customer is happy with your reading.", "narrative_failure": "Look again at the words the customer used.", "concept": "Using context to find a word’s meaning.", "level": "beginner", "level_label": "Beginner", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “It was a cold morning. Kemi wore a thick sweater and warm socks before she left home.” Why did Kemi wear a thick sweater?", "options": ["A. She wanted to look tall", "B. The morning was cold", "C. She was going to swim", "D. She had no uniform"], "answer": "B. The morning was cold", "narrative_success": "Spot on. The customer is happy with your reading.", "narrative_failure": "Look again at the words the customer used.", "concept": "Finding the reason for something.", "level": "beginner", "level_label": "Beginner", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Ngozi was late for school because the bus broke down on the way.” Why was Ngozi late?", "options": ["A. She woke up late", "B. The bus broke down", "C. She lost her bag", "D. She was ill"], "answer": "B. The bus broke down", "narrative_success": "Spot on. The customer is happy with your reading.", "narrative_failure": "Look again at the words the customer used.", "concept": "Finding the reason for something.", "level": "beginner", "level_label": "Beginner", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Segun opened his umbrella, put on his raincoat and stepped outside.” What can we guess about the weather?", "options": ["A. It was probably raining", "B. It was very dry and hot", "C. It was a public holiday", "D. It was midnight"], "answer": "A. It was probably raining", "narrative_success": "Sharp thinking. You read between the lines like a pro.", "narrative_failure": "Think about the clues and try the next order.", "concept": "Making an inference from clues.", "level": "intermediate", "level_label": "Intermediate", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Ada kept looking at her watch and tapping her foot. At last, the taxi arrived and she rushed in.” How did Ada probably feel while she waited?", "options": ["A. Calm and sleepy", "B. Impatient", "C. Proud", "D. Sad"], "answer": "B. Impatient", "narrative_success": "Sharp thinking. You read between the lines like a pro.", "narrative_failure": "Think about the clues and try the next order.", "concept": "Inferring feelings from actions.", "level": "intermediate", "level_label": "Intermediate", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “The market was empty. The shop doors were locked, and a sign on the gate said, ‘Closed for the festival. Back on Thursday.’” Why was the market empty?", "options": ["A. A festival was being celebrated", "B. The shops had nothing to sell", "C. It was raining heavily", "D. Thieves had come"], "answer": "A. A festival was being celebrated", "narrative_success": "Sharp thinking. You read between the lines like a pro.", "narrative_failure": "Think about the clues and try the next order.", "concept": "Using a sign as evidence.", "level": "intermediate", "level_label": "Intermediate", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “After the match, Musa’s team lifted the cup while the crowd sang and clapped.” Which statement is true?", "options": ["A. Musa’s team won", "B. The match was cancelled", "C. The crowd left early", "D. Musa’s team lost"], "answer": "A. Musa’s team won", "narrative_success": "Sharp thinking. You read between the lines like a pro.", "narrative_failure": "Think about the clues and try the next order.", "concept": "Drawing a conclusion.", "level": "intermediate", "level_label": "Intermediate", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Tola’s plant turned yellow and dropped its leaves. She had forgotten to water it for three weeks.” What most likely made the plant turn yellow?", "options": ["A. Too much shade", "B. It was not watered", "C. It was too young", "D. A bird ate it"], "answer": "B. It was not watered", "narrative_success": "Sharp thinking. You read between the lines like a pro.", "narrative_failure": "Think about the clues and try the next order.", "concept": "Finding cause and effect.", "level": "intermediate", "level_label": "Intermediate", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: ““I have never seen such a huge crowd,” said Ibrahim, staring at the stadium.” What does Ibrahim’s remark show?", "options": ["A. He was surprised by the size of the crowd", "B. He was bored", "C. He was angry", "D. He had been to the stadium many times"], "answer": "A. He was surprised by the size of the crowd", "narrative_success": "Sharp thinking. You read between the lines like a pro.", "narrative_failure": "Think about the clues and try the next order.", "concept": "Understanding what a speaker means.", "level": "intermediate", "level_label": "Intermediate", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Which word is the noun form of ‘decide’?", "options": ["A. Decisive", "B. Decision", "C. Decidedly", "D. Decided"], "answer": "B. Decision", "narrative_success": "Excellent word sense. The menu is no secret to you.", "narrative_failure": "Check the meaning in the sentence and try again.", "concept": "Word families.", "level": "advanced", "level_label": "Advanced", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “The teacher was delighted with the pupils’ neat work and praised each of them.” Which word is closest in meaning to ‘delighted’?", "options": ["A. Disappointed", "B. Pleased", "C. Puzzled", "D. Tired"], "answer": "B. Pleased", "narrative_success": "Excellent word sense. The menu is no secret to you.", "narrative_failure": "Check the meaning in the sentence and try again.", "concept": "Synonyms in context.", "level": "advanced", "level_label": "Advanced", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Which word is opposite in meaning to ‘generous’?", "options": ["A. Kind", "B. Selfish", "C. Rich", "D. Polite"], "answer": "B. Selfish", "narrative_success": "Excellent word sense. The menu is no secret to you.", "narrative_failure": "Check the meaning in the sentence and try again.", "concept": "Antonyms.", "level": "advanced", "level_label": "Advanced", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Though the road was long and rough, the drivers pressed on.” What does ‘pressed on’ mean here?", "options": ["A. Continued their journey", "B. Stopped to rest", "C. Turned back", "D. Pushed the cars"], "answer": "A. Continued their journey", "narrative_success": "Excellent word sense. The menu is no secret to you.", "narrative_failure": "Check the meaning in the sentence and try again.", "concept": "Understanding a phrase from its sentence.", "level": "advanced", "level_label": "Advanced", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “The farmer was jubilant when the rains finally came after months of drought.” What does ‘jubilant’ mean?", "options": ["A. Very happy", "B. Very angry", "C. Very tired", "D. Very afraid"], "answer": "A. Very happy", "narrative_success": "Excellent word sense. The menu is no secret to you.", "narrative_failure": "Check the meaning in the sentence and try again.", "concept": "Using context to find a word’s meaning.", "level": "advanced", "level_label": "Advanced", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Which word means ‘not happy’?", "options": ["A. Unhappy", "B. Rehappy", "C. Overhappy", "D. Happily"], "answer": "A. Unhappy", "narrative_success": "Excellent word sense. The menu is no secret to you.", "narrative_failure": "Check the meaning in the sentence and try again.", "concept": "Prefixes.", "level": "advanced", "level_label": "Advanced", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Honesty costs little but earns a lot: people who tell the truth are trusted, and trusted people are given more chances.” Which statement best sums up the message?", "options": ["A. Telling the truth earns trust and more chances.", "B. Honest people never make mistakes.", "C. Chances are given only to rich people.", "D. It costs money to be honest."], "answer": "A. Telling the truth earns trust and more chances.", "narrative_success": "Boss cleared. You understood the whole message.", "narrative_failure": "The boss is tough. Read it once more, carefully.", "concept": "Summarising a message.", "level": "challenge", "level_label": "Boss Battle", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “The town had no clean water, so mothers walked two hours each day to a stream. When the council dug a borehole, children began to arrive at school earlier and healthier.” What was the effect of the borehole?", "options": ["A. Children arrived at school earlier and healthier", "B. The stream dried up", "C. Mothers walked farther", "D. The council closed the school"], "answer": "A. Children arrived at school earlier and healthier", "narrative_success": "Boss cleared. You understood the whole message.", "narrative_failure": "The boss is tough. Read it once more, carefully.", "concept": "Finding an effect.", "level": "challenge", "level_label": "Boss Battle", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Reading is a journey you can take without leaving your chair.” What does this sentence mean?", "options": ["A. Reading lets you imagine new places while sitting still", "B. You must travel in order to read", "C. Chairs are needed for every journey", "D. Reading is very tiring"], "answer": "A. Reading lets you imagine new places while sitting still", "narrative_success": "Boss cleared. You understood the whole message.", "narrative_failure": "The boss is tough. Read it once more, carefully.", "concept": "Understanding figurative language.", "level": "challenge", "level_label": "Boss Battle", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Ada saved ₦200 each week. After eight weeks she bought a book costing ₦1,500.” How much money was left after she bought the book?", "options": ["A. ₦50", "B. ₦100", "C. ₦150", "D. ₦1,600"], "answer": "B. ₦100", "narrative_success": "Boss cleared. You understood the whole message.", "narrative_failure": "The boss is tough. Read it once more, carefully.", "concept": "Combining reading with calculation.", "level": "challenge", "level_label": "Boss Battle", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "Read: “Few pupils came to the debate because the notice was pinned behind the library door where nobody looked.” What was the main reason few pupils came?", "options": ["A. The notice was put where it could not be seen", "B. The debate was boring", "C. It was raining", "D. The library was closed forever"], "answer": "A. The notice was put where it could not be seen", "narrative_success": "Boss cleared. You understood the whole message.", "narrative_failure": "The boss is tough. Read it once more, carefully.", "concept": "Finding the main reason.", "level": "challenge", "level_label": "Boss Battle", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}, {"type": "multiple_choice", "question": "A story is about a boy who finds a lost puppy and returns it to its owner. Which is the best title?", "options": ["A. The Honest Boy and the Puppy", "B. A Rainy Day", "C. Bread for Breakfast", "D. The Long Road to Lagos"], "answer": "A. The Honest Boy and the Puppy", "narrative_success": "Boss cleared. You understood the whole message.", "narrative_failure": "The boss is tough. Read it once more, carefully.", "concept": "Choosing a title.", "level": "challenge", "level_label": "Boss Battle", "world_theme": "Pizza Shop Adventure", "tag": "selfcontained_v1"}]$j$::jsonb
 where c.topic = 'Comprehension & Vocabulary'
   and c.class_level = 'Primary 5'
   and c.institution_id = (select id from public.institutions where name ilike '%grace bells%' limit 1)
   and not exists (
     select 1 from jsonb_array_elements(c.generated_questions) e where e->>'tag' = 'selfcontained_v1'
   );
